const projects=[
{id:'convy',title:'Convy',type:'Business communication platform',status:'Independent product',category:'product data',stack:['Spring Boot','React / TypeScript','Azure','Redis'],description:'A connected workspace for WhatsApp conversations, campaigns, and customer journeys.',problem:'Customer conversations, campaign operations, and follow-up workflows often live in disconnected tools.',build:'An independent multi-tenant communication product combining a shared inbox, message templates, campaign uploads, journey automation, and CRM integration workflows. The platform spans a Spring Boot backend, React frontend, and NestJS realtime gateway.',flow:'React workspace → Spring Boot API → messaging & automation workflows → event delivery → realtime inbox',focus:'API contracts, asynchronous processing, tenant context, campaign pacing, and end-to-end integration behavior. Cloud work includes Azure staging deployment and operational cost management.',scope:'Ongoing independent product development. AI capabilities and additional communication channels are separate roadmap work.',url:'https://convy.in',link:'Visit Convy',art:'<div class="mock"><div class="mock-head"><span>convy<span style="color:#7e9a36">.</span></span><span class="tiny">Shared inbox</span></div><div class="mock-body"><div class="sidebar">◉ Inbox<br>▦ Campaigns<br>⌘ Journeys<br>♧ Contacts</div><div class="inbox"><div class="tiny" style="margin-bottom:13px">CUSTOMER CONVERSATION</div><div class="bubble">Can you share more details?</div><div class="bubble reply">Absolutely. Let’s find the right fit.</div><div class="tiny">Assigned · Team workspace</div></div></div></div>'},
{id:'copilot',title:'AI Sales Copilot',type:'Retrieval-augmented assistance',status:'Working prototype',category:'ai',stack:['FastAPI','FAISS','Ollama / Qwen','WebSockets'],description:'Context-aware next-response suggestions for sales conversations, backed by retrieved product knowledge.',problem:'During a sales conversation, an agent needs relevant product context without searching a knowledge base manually.',build:'A React and FastAPI application that accepts customer and SDR text turns over WebSockets. EmbeddingGemma and FAISS retrieve relevant passages, and a local Qwen3 model generates structured recommendations with rationale, next action, sources, and timing.',flow:'Conversation turn → history → embeddings & FAISS retrieval → Qwen3 via Ollama → structured recommendation',focus:'Latest-turn priority, stale-result handling, source references, JSON validation, scenario evaluation, and the quality/latency trade-off of local inference.',scope:'Transcript-driven interview MVP using a fictitious product knowledge base. Live telephone transcription, persistent sessions, and production deployment are outside the current implementation. Suggestions require human review.',url:gh+'realtime-ai-sales-copilot',link:'View repository',art:'<div class="mock"><div class="mock-head"><span>✳ sales copilot</span><span style="color:#b7c9a0">● Local inference</span></div><div class="inbox"><div class="tiny" style="color:#b6b5c8">CONVERSATION CONTEXT → RETRIEVED KNOWLEDGE</div><div class="wave">'+Array(36).fill('<i></i>').join('')+'</div><div class="suggest"><small>✳ NEXT RESPONSE · ILLUSTRATIVE</small>How are you managing follow-ups with your team today?</div><p class="tiny" style="color:#b6b5c8;margin:10px 0 0">Recommendation · Rationale · Sources</p></div></div>'},
{id:'lead',title:'Lead Intelligence',type:'Predictive sales prioritization',status:'ML exploration',category:'ai data',stack:['Python','XGBoost','scikit-learn','FastAPI'],description:'Exploring how CRM signals can help sales teams prioritize leads for follow-up.',problem:'Sales teams need a repeatable way to decide which leads to contact first, rather than relying only on intuition.',build:'A lead-scoring proof of concept exploring CRM data preparation, behavioral and contextual features, classification, and ranked lead scores. Related work includes an AI intelligence dashboard and service exploration.',flow:'CRM data → cleaning & features → classification model → lead score → prioritization interface',focus:'Feature quality, label definitions, evaluation, data leakage, and translating scores into understandable follow-up priorities.',scope:'Portfolio and learning work. Public repositories contain documentation and related implementation experiments; production scale and business-impact metrics are not asserted.',url:gh+'AI-Lead-Intelligence-Engine',link:'Explore related repository',art:'<div class="mock"><div class="mock-head"><span>Lead intelligence</span><span class="tiny">PRIORITIZATION</span></div><div class="inbox" style="padding-bottom:0"><div class="tiny">FROM CRM SIGNALS TO ACTION</div><div style="font-size:22px;letter-spacing:-1px;margin-top:5px">Find the next best conversation.</div></div><div class="chart"><i style="height:24%"></i><i style="height:40%"></i><i style="height:34%"></i><i style="height:61%"></i><i style="height:72%"></i><i style="height:64%"></i><i style="height:88%"></i></div><div class="mock-bottom"><span>Signals → Model → Score</span><span class="tiny">Concept illustration</span></div></div>'},
{id:'northstar',title:'Northstar CRM',type:'Integration engineering',status:'Local application',category:'product data',stack:['Python','SQLite','REST APIs','Webhooks / OAuth'],description:'An independent CRM and integration lab built to test how external systems connect and recover.',problem:'Reliable integrations need realistic failure scenarios: duplicates, timeouts, stale updates, token expiry, and interrupted delivery.',build:'A single-owner local CRM with customer and opportunity management, scoped API keys, a bounded OAuth test provider, signed webhooks, a cursor-based changes feed, and durable delivery processing.',flow:'CRM write → transaction & outbox → webhook / polling → external consumer inbox → deduplicated effect',focus:'Idempotency, replay, signature verification, authentication, optimistic versioning, retry behavior, and restart recovery. External connectors use the CRM’s own independent contract.',scope:'Local integration-testing application with SQLite. Source is private. It is not a managed multi-tenant CRM or an audited identity provider.',art:'<div class="mock"><div class="mock-head"><span>✦ northstar</span><span class="tiny">OPPORTUNITY PIPELINE</span></div><div class="kanban"><div>Prospect<b>New opportunity</b><b>Initial inquiry</b></div><div>Discovery<b>Requirements</b><b>Team follow-up</b></div><div>Proposal<b>Solution review</b></div></div><div class="mock-bottom"><span>↗ Signed webhook</span><span class="tiny">Durable delivery · Replay</span></div></div>'},
{id:'lila',title:'Player Journey Explorer',type:'Interactive data visualization',status:'Hosted assignment',category:'product data',stack:['React','TypeScript','Canvas 2D','Python / PyArrow'],description:'A level-design tool that turns match telemetry into player paths, playback, and spatial heatmaps.',problem:'Raw match telemetry makes it difficult to understand how players move, where encounters happen, and how map areas are used.',build:'A Python data pipeline and React/Canvas interface for exploring player journeys across three game maps. The interface includes map/day/match filters, human and bot paths, event markers, playback, and traffic/kill/death heatmaps.',flow:'Match data → Python preprocessing → static data assets → Canvas map projection → filters & playback',focus:'Coordinate projection, map placement, spatial aggregation, rendering, and explaining assumptions through architecture notes and evidenced findings.',scope:'LILA Games product-engineering take-home project. The repository documents setup, pipeline assumptions, tests, and insights.',url:gh+'lila-games-assignment',link:'View repository',demo:'https://lila-games-assignment-one.vercel.app/',art:'<div class="map"></div><span class="map-label">PLAYER PATHS / SPATIAL INSIGHTS</span>'},
{id:'sales',title:'SalesFlow',type:'Contact management',status:'Engineering exploration',category:'product',stack:['Java','Spring Boot','React','PostgreSQL'],description:'A full-stack exploration of contact workflows, service boundaries, and a sales workspace.',problem:'Contact information and interactions need a structured home that can grow alongside sales workflows.',build:'Related frontend and backend repositories exploring a contact-management workspace. The backend includes a Spring Boot contact core service, with broader service boundaries described in the architecture documentation.',flow:'React sales workspace → REST interfaces → Spring Boot contact core → database workflows',focus:'Domain modeling, API boundaries, frontend/backend integration, and organizing a business application for maintainability.',scope:'Independent engineering exploration. Architecture documentation includes broader planned components; those are not presented as verified deployed services.',url:gh+'SalesFlow-BE',link:'View backend',demo:gh+'SalesFlow-FE',demoLabel:'View frontend',art:'<div class="mock"><div class="mock-head"><span>salesflow / contacts</span><span class="tiny">WORKSPACE</span></div><div class="inbox"><div class="tiny" style="margin-bottom:14px">PEOPLE. CONTEXT. NEXT STEPS.</div>'+['Contact directory','Interaction history','Follow-up workflow'].map((x,i)=>'<div style="padding:10px 0;border-bottom:1px solid #e8e8df;display:flex;gap:12px"><span style="color:#7c8c53">0'+(i+1)+'</span>'+x+'</div>').join('')+'</div></div>'}
];
const container=document.querySelector('#projects');
container.innerHTML=projects.map((p,i)=>`<article class="project" data-category="${p.category}"><div class="art ${p.id}"><span class="art-caption">Interface concept / ${String(i+1).padStart(2,'0')}</span>${p.art}</div><div class="project-meta"><span>${p.type}</span><span>${p.status}</span></div><div class="project-title"><h3>${p.title}</h3><button class="case" data-id="${p.id}" aria-label="Explore ${p.title} case study">↗</button></div><p>${p.description}</p><div class="tags">${p.stack.map(t=>`<span>${t}</span>`).join('')}</div></article>`).join('');
const archive=[['Real Estate AI Voice Agent','Voice & RAG exploration','AI-voice-agent-LLM-RAG'],['IdeaScribe','Flask & OpenAI idea-generation experiment','IdeascribeApp'],['Hospital Management System','Spring Boot & frontend application','Hospital-Management-System'],['Multiple Disease Prediction','Educational Streamlit ML application','public_ml_web_app'],['Livestream Overlay App','React interface project','livestream-overlay-app-new'],['Java E-commerce System','Java application exercise','ecommerce-system-java'],['React Projects','Frontend practice & smaller builds','React-Projects'],['ML Projects','Machine-learning learning repository','ML-Projects'],['Campaign Message Generator','Messaging experiment','campaign-message-generator'],['Flask Notes App','Python web application','flask-notes-app']];
document.querySelector('#archive').innerHTML=archive.map(([title,sub,repo])=>`<a class="archive-item" href="${gh+repo}" target="_blank" rel="noopener"><span>${title}<small>${sub}</small></span><span>↗</span></a>`).join('');
document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')});b.classList.add('active');b.setAttribute('aria-pressed','true');document.querySelectorAll('.project').forEach(p=>p.hidden=b.dataset.filter!=='all'&&!p.dataset.category.split(' ').includes(b.dataset.filter));}));
const dialog=document.querySelector('#detail');
document.querySelectorAll('.case').forEach(b=>b.addEventListener('click',()=>{const p=projects.find(x=>x.id===b.dataset.id);document.querySelector('#dialog-content').innerHTML=`<span class="eyebrow">${p.type} / ${p.status}</span><h2 id="dialog-title">${p.title}</h2><div class="tags">${p.stack.map(t=>`<span>${t}</span>`).join('')}</div><h3>The problem</h3><p>${p.problem}</p><h3>The build</h3><p>${p.build}</p><div class="flow">${p.flow}</div><h3>Engineering focus</h3><p>${p.focus}</p><h3>Project scope</h3><p>${p.scope}</p><div class="dialog-links">${p.url?`<a class="btn primary" href="${p.url}" target="_blank" rel="noopener">${p.link} ↗</a>`:''}${p.demo?`<a class="btn" href="${p.demo}" target="_blank" rel="noopener">${p.demoLabel||'Open live project'} ↗</a>`:''}</div>`;dialog.showModal();}));
dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelector('#copy').addEventListener('click',async()=>{const toast=document.querySelector('#toast');try{await navigator.clipboard.writeText('akshay@convy.in');toast.textContent='Email address copied';}catch{toast.textContent='Email: akshay@convy.in';}toast.style.display='block';setTimeout(()=>toast.style.display='none',3000)});document.querySelector('#year').textContent=new Date().getFullYear();
